drop policy if exists antimicrobial_therapies_insert on public.antimicrobial_therapies; create policy antimicrobial_therapies_insert on public.antimicrobial_therapies for insert to authenticated with check (current_user_has_org_role(organization_id, array['infection_control_lead'::app_role,'doctor_reviewer'::app_role,'pharmacy'::app_role,'laboratory'::app_role])); drop policy if exists antimicrobial_therapies_read on public.antimicrobial_therapies; create policy antimicrobial_therapies_read on public.antimicrobial_therapies for select to authenticated using (current_user_is_platform_owner() or current_user_has_org_role(organization_id, array['infection_control_lead'::app_role,'infection_control_member'::app_role,'pharmacy'::app_role,'doctor_reviewer'::app_role,'laboratory'::app_role]));
